<?php require_once __DIR__.'/../src/App.php'; require_once __DIR__.'/../src/LoanView.php'; require_once __DIR__.'/../src/Repository.php';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH) ?: '/';
$staticRoot=realpath(__DIR__.'/../static');$requested=realpath($staticRoot.'/'.ltrim(substr($path,8),'/'));
if(str_starts_with($path,'/static/') && $staticRoot && $requested && str_starts_with($requested,$staticRoot.DIRECTORY_SEPARATOR) && is_file($requested)){ $types=['css'=>'text/css; charset=utf-8','js'=>'application/javascript; charset=utf-8','webmanifest'=>'application/manifest+json','svg'=>'image/svg+xml'];$ext=strtolower(pathinfo($requested,PATHINFO_EXTENSION));header('Content-Type',$types[$ext]??'application/octet-stream');readfile($requested);exit; }
$action=$_POST['action']??'';
if($_SERVER['REQUEST_METHOD']==='POST' && in_array($action,['participant_update','participant_toggle','participant_delete'],true)){$db=Database::connection();$id=(int)$_POST['participant_id'];if($action==='participant_update'){$s=$db->prepare('UPDATE participants SET full_name=?,document=?,phone=?,email=? WHERE id=?');$s->execute([trim($_POST['full_name']),trim($_POST['document']),trim($_POST['phone']??''),trim($_POST['email']??''),$id]);}elseif($action==='participant_toggle'){$s=$db->prepare('UPDATE participants SET active=1-active WHERE id=?');$s->execute([$id]);}else{(new Repository($db))->deleteParticipant($id);}header('Location: /participants');exit;}
if(preg_match('#^/loans/(\d+)$#',$path,$match)){
  $db=Database::connection();
  if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='installment'){ $s=$db->prepare('UPDATE loan_installments SET paid_amount=LEAST(total_amount,GREATEST(0,paid_amount+?)) WHERE id=?');$s->execute([(float)($_POST['amount']??0),(int)$_POST['installment_id']]); header('Location: '.$path);exit; }
  echo '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plan de pagos</title><link rel="manifest" href="/static/manifest.webmanifest"><link rel="apple-touch-icon" href="/static/icons/icon.svg"><link rel="stylesheet" href="/static/app.css"><link rel="stylesheet" href="/static/v2.css"></head><body><nav><a class="brand" href="/">Ｎ Natillera <small>FINANCIERA</small></a><a href="/">Ahorros</a><a href="/participants">Participantes</a><a href="/loans">Préstamos</a><a href="/reports/annual">Reportes</a></nav><main>'.LoanView::render($db,(int)$match[1]).'</main><script src="/static/v2.js" defer></script><script>if("serviceWorker" in navigator)navigator.serviceWorker.register("/static/sw.js")</script></body></html>';exit;
}
ob_start(); App::run(); $html=ob_get_clean();
$months=['January'=>'Enero','February'=>'Febrero','March'=>'Marzo','April'=>'Abril','May'=>'Mayo','June'=>'Junio','July'=>'Julio','August'=>'Agosto','September'=>'Septiembre','October'=>'Octubre','November'=>'Noviembre','December'=>'Diciembre'];$html=str_replace(array_keys($months),array_values($months),$html);
if($path==='/participants'){$ids=Database::connection()->query('SELECT id,full_name,document,phone,email FROM participants ORDER BY active DESC,full_name')->fetchAll();$n=0;$html=preg_replace_callback('#<article class="card">(.*?)</article>#s',function($m)use(&$n,$ids){$p=$ids[$n++]??[];$id=(int)($p['id']??0);return '<article class="card">'.$m[1].'<details><summary>Editar</summary><form method="post"><input type="hidden" name="action" value="participant_update"><input type="hidden" name="participant_id" value="'.$id.'"><input name="full_name" value="'.htmlspecialchars($p['full_name']??'',ENT_QUOTES).'" required><input name="document" value="'.htmlspecialchars($p['document']??'',ENT_QUOTES).'" required><input name="phone" value="'.htmlspecialchars($p['phone']??'',ENT_QUOTES).'" placeholder="Teléfono"><input name="email" value="'.htmlspecialchars($p['email']??'',ENT_QUOTES).'" placeholder="Correo"><button>Guardar cambios</button></form></details><div class="actions"><form method="post"><input type="hidden" name="action" value="participant_toggle"><input type="hidden" name="participant_id" value="'.$id.'"><button>Desactivar / Activar</button></form><form method="post"><input type="hidden" name="action" value="participant_delete"><input type="hidden" name="participant_id" value="'.$id.'"><button>Eliminar</button></form></div></article>';},$html);}
if($path==='/loans')$html=str_replace('</article>','<small>Tasa · Estado</small></article>',$html);
if(str_starts_with($path,'/reports')){$html=str_replace('<section class="card"><strong>Total</strong></section>','',$html);if(strpos($html,'method-toggle')===false)$html=str_replace('</main>','<section class="method"><button class="method-toggle" type="button">ⓘ ¿Cómo se calcula?</button><div class="method-popover">Se suman los intereses de las cuotas con vencimiento dentro del año consultado, tanto de préstamos propios al 5% como de préstamos a referidos al 10%. La ganancia total se divide en partes iguales entre los participantes activos y se suma al ahorro individual de enero a noviembre.</div></section></main>',$html);}
echo $html.'<link rel="stylesheet" href="/static/v2.css"><script src="/static/v2.js" defer></script>';
